<?php require __DIR__.'/ui.php';auth();$p=db();$id=(int)($_GET['order_id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$p->prepare("INSERT INTO order_timeline(order_id,event_type,title,details,user_id)VALUES(?,?,?,?,?)")->execute([$id,'manual',$_POST['title'],$_POST['details'],current_user()['id']??null]);go('timeline.php?order_id='.$id);}$s=$p->prepare("SELECT t.*,u.name user_name FROM order_timeline t LEFT JOIN users u ON u.id=t.user_id WHERE order_id=? ORDER BY id DESC");$s->execute([$id]);$rows=$s->fetchAll();page_head('Timeline do pedido #'.$id);?><div class="grid g2"><div class="card"><form method="post"><?=csrf_field()?><label>Evento</label><input name="title" required><label>Detalhes</label><textarea name="details"></textarea><button class="primary">Registrar</button></form></div><div class="card"><?php foreach($rows as $x):?><div class="ticket"><b><?=e($x['title'])?></b><small><?=e($x['created_at'])?> • <?=e($x['user_name'])?></small><p><?=e($x['details'])?></p></div><?php endforeach;?></div></div><?php page_foot();?>